<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/includes/bootstrap.php';
$currentAdmin=require_permission('catalog.manage');
$editId=filter_var($_GET['edit']??null,FILTER_VALIDATE_INT);$editItem=null;
if($editId){$s=db()->prepare('SELECT * FROM catalog_items WHERE id=:id');$s->execute(['id'=>$editId]);$editItem=$s->fetch()?:null;}
$form=['item_type'=>$editItem['item_type']??'service','name'=>$editItem['name']??'','description'=>$editItem['description']??'','unit_price'=>(string)($editItem['unit_price']??0),'sort_order'=>(string)($editItem['sort_order']??0)];$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();$action=(string)($_POST['action']??'save');
    if($action==='toggle'){
        $id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);if($id){$u=db()->prepare("UPDATE catalog_items SET status=IF(status='active','inactive','active') WHERE id=:id");$u->execute(['id'=>$id]);audit_log('toggled','catalog_item',(int)$id,'Estado de ítem del catálogo modificado');flash('success','Estado del catálogo actualizado.');}redirect_admin('cotizaciones/catalogo.php');
    }
    $form=['item_type'=>(string)($_POST['item_type']??'service'),'name'=>trim((string)($_POST['name']??'')),'description'=>trim((string)($_POST['description']??'')),'unit_price'=>trim((string)($_POST['unit_price']??'0')),'sort_order'=>trim((string)($_POST['sort_order']??'0'))];
    $id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);
    if(!in_array($form['item_type'],['service','product'],true))$errors[]='Selecciona un tipo válido.';
    if(mb_strlen($form['name'])<2||mb_strlen($form['name'])>180)$errors[]='El nombre debe tener entre 2 y 180 caracteres.';
    if(mb_strlen($form['description'])>1000)$errors[]='La descripción es demasiado extensa.';
    if(!preg_match('/^[0-9]+$/',$form['unit_price'])||(int)$form['unit_price']>1000000000)$errors[]='El precio no es válido.';
    if(!preg_match('/^[0-9]+$/',$form['sort_order'])||(int)$form['sort_order']>65000)$errors[]='El orden no es válido.';
    if(!$errors){$params=['item_type'=>$form['item_type'],'name'=>$form['name'],'description'=>$form['description']?:null,'unit_price'=>(int)$form['unit_price'],'sort_order'=>(int)$form['sort_order']];if($id){$params['id']=$id;$q=db()->prepare('UPDATE catalog_items SET item_type=:item_type,name=:name,description=:description,unit_price=:unit_price,sort_order=:sort_order WHERE id=:id');$q->execute($params);audit_log('updated','catalog_item',(int)$id,'Ítem de catálogo actualizado');}else{$q=db()->prepare('INSERT INTO catalog_items(item_type,name,description,unit_price,sort_order) VALUES(:item_type,:name,:description,:unit_price,:sort_order)');$q->execute($params);audit_log('created','catalog_item',(int)db()->lastInsertId(),'Ítem de catálogo creado');}flash('success','Catálogo guardado.');redirect_admin('cotizaciones/catalogo.php');}
}
$catalog=db()->query('SELECT * FROM catalog_items ORDER BY sort_order,name')->fetchAll();$pageTitle='Catálogo comercial';$activeMenu='quotes';require dirname(__DIR__).'/includes/header.php';
?>
<div class="page-heading"><div><span class="page-heading__eyebrow">Cotización rápida</span><h1>Catálogo</h1><p>Define servicios, productos y precios base que podrás agregar con un clic.</p></div><a class="btn btn-outline-dark" href="<?= e(admin_url('cotizaciones/')) ?>">Volver a cotizaciones</a></div>
<?php if($errors):?><div class="alert alert-danger"><ul class="mb-0"><?php foreach($errors as $error):?><li><?= e($error) ?></li><?php endforeach;?></ul></div><?php endif;?>
<div class="row g-4"><div class="col-xl-5"><section class="form-section"><div class="form-section__heading"><h2><?= $editItem?'Editar ítem':'Nuevo ítem' ?></h2><p>El precio siempre podrá cambiarse dentro de una cotización.</p></div><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="save"><?php if($editItem):?><input type="hidden" name="id" value="<?= (int)$editItem['id'] ?>"><?php endif;?><div class="row g-3"><div class="col-md-4"><label class="form-label">TIPO</label><select class="form-select" name="item_type"><option value="service"<?= $form['item_type']==='service'?' selected':'' ?>>Servicio</option><option value="product"<?= $form['item_type']==='product'?' selected':'' ?>>Producto</option></select></div><div class="col-md-8"><label class="form-label">NOMBRE</label><input class="form-control" name="name" value="<?= e($form['name']) ?>" maxlength="180" required></div><div class="col-12"><label class="form-label">DESCRIPCIÓN</label><textarea class="form-control" name="description" rows="4" maxlength="1000"><?= e($form['description']) ?></textarea></div><div class="col-md-8"><label class="form-label">PRECIO BASE</label><div class="input-group"><span class="input-group-text">$</span><input class="form-control" name="unit_price" type="number" min="0" max="1000000000" value="<?= e($form['unit_price']) ?>"></div></div><div class="col-md-4"><label class="form-label">ORDEN</label><input class="form-control" name="sort_order" type="number" min="0" max="65000" value="<?= e($form['sort_order']) ?>"></div></div><div class="d-flex gap-2 mt-4"><button class="btn btn-primary"><?= $editItem?'Guardar cambios':'Agregar al catálogo' ?></button><?php if($editItem):?><a class="btn btn-outline-dark" href="<?= e(admin_url('cotizaciones/catalogo.php')) ?>">Cancelar</a><?php endif;?></div></form></section></div><div class="col-xl-7"><section class="admin-card"><div class="admin-card__header"><h2>Servicios y productos</h2><span class="status-badge status-badge--active"><?= count($catalog) ?> ítems</span></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Ítem</th><th>Tipo</th><th>Precio</th><th>Estado</th><th class="text-end">Acciones</th></tr></thead><tbody><?php foreach($catalog as $item):?><tr><td><strong><?= e($item['name']) ?></strong><small class="d-block text-secondary catalog-description"><?= e($item['description']??'') ?></small></td><td><span class="role-badge"><?= $item['item_type']==='product'?'Producto':'Servicio' ?></span></td><td><strong>$<?= number_format((int)$item['unit_price'],0,',','.') ?></strong></td><td><span class="status-badge status-badge--<?= $item['status']==='active'?'active':'inactive' ?>"><?= $item['status']==='active'?'Activo':'Inactivo' ?></span></td><td><div class="d-flex justify-content-end gap-1"><a class="btn btn-sm btn-outline-dark" href="<?= e(admin_url('cotizaciones/catalogo.php?edit='.(int)$item['id'])) ?>">Editar</a><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?= (int)$item['id'] ?>"><button class="btn btn-sm btn-outline-dark"><?= $item['status']==='active'?'Desactivar':'Activar' ?></button></form></div></td></tr><?php endforeach;?></tbody></table></div></section></div></div>
<?php require dirname(__DIR__).'/includes/footer.php'; ?>
